import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2.57.4";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey",
};

const LOGO_BLUE_B64 = "";
const LOGO_WHITE_B64 = "";

// ────── BEGIN AUTOGENERATED LOGO BASE64 ──────
const LOGO_ON_WHITE_B64 = "";
const LOGO_ON_WHITE_2X_B64 = "";
const LOGO_ON_DARK_B64 = "";
const LOGO_ON_DARK_2X_B64 = "";
// ────── END AUTOGENERATED LOGO BASE64 ──────

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    const results: string[] = [];

    for (const [filename, b64str] of Object.entries({
      "logo-blue.png":         LOGO_BLUE_B64,
      "logo-white.png":        LOGO_WHITE_B64,
      "logo-on-white.png":     LOGO_ON_WHITE_B64,
      "logo-on-white@2x.png":  LOGO_ON_WHITE_2X_B64,
      "logo-on-dark.png":      LOGO_ON_DARK_B64,
      "logo-on-dark@2x.png":   LOGO_ON_DARK_2X_B64,
    }) as [string, string][]) {
      const binaryStr = atob(b64str);
      const bytes = new Uint8Array(binaryStr.length);
      for (let i = 0; i < binaryStr.length; i++) {
        bytes[i] = binaryStr.charCodeAt(i);
      }
      const { error } = await supabase.storage
        .from("email-assets")
        .upload(filename, bytes, { contentType: "image/png", upsert: true });
      results.push(filename + ": " + (error ? error.message : "OK"));
    }

    return new Response(JSON.stringify({ results }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: String(e) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});
